console.log('argvUser  =' + JSON.stringify(process.argv.slice(2).map(s => Buffer.from(s, 'utf8').toString('hex'))));

// strict UTF-8 validator on raw bytes
function isStrictUtf8(buf) {
  let i = 0;
  while (i < buf.length) {
    const b = buf[i];
    let len, min;
    if (b < 0x80) { i++; continue; }
    else if (b >= 0xC2 && b <= 0xDF) { len = 2; }
    else if (b >= 0xE0 && b <= 0xEF) { len = 3; }
    else if (b >= 0xF0 && b <= 0xF4) { len = 4; }
    else return false;
    if (i + len > buf.length) return false;
    for (let k = 1; k < len; k++) if ((buf[i + k] & 0xC0) !== 0x80) return false;
    let cp;
    if (len === 2) cp = ((b & 0x1F) << 6) | (buf[i+1] & 0x3F);
    else if (len === 3) cp = ((b & 0x0F) << 12) | ((buf[i+1] & 0x3F) << 6) | (buf[i+2] & 0x3F);
    else cp = ((b & 0x07) << 18) | ((buf[i+1] & 0x3F) << 12) | ((buf[i+2] & 0x3F) << 6) | (buf[i+3] & 0x3F);
    if (len === 2 && cp < 0x80) return false;
    if (len === 3 && cp < 0x800) return false;
    if (len === 4 && cp < 0x10000) return false;
    if (cp >= 0xD800 && cp <= 0xDFFF) return false;
    if (cp > 0x10FFFF) return false;
    i += len;
  }
  return true;
}
